import{z as i,x as d,o as e,c as D,q as l,j as t,D as a,d as A,s as o,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"ZeRO 的各阶段","description":"","frontmatter":{"title":"ZeRO 的各阶段","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-zero-stages.md","filePath":"llm/dist-zero-stages.md","lastUpdated":1791413859000}'),n={name:"llm/dist-zero-stages.md"};function p(h,E,m,C,f,c){const r=d("Mermaid");return e(),D("div",null,[E[2]||(E[2]=l('<h1 id="zero-的各阶段" tabindex="-1">ZeRO 的各阶段 <a class="header-anchor" href="#zero-的各阶段" aria-label="Permalink to &quot;ZeRO 的各阶段&quot;">​</a></h1><div class="epigraph"><p>档位是显存与通信时序的合同：第一刀几乎免费，第三刀开始为每一次前向付聚集税。</p><footer>—— Rajbhandari 等，ZeRO 与 DeepSpeed 系列</footer></div><p><a href="/llm/dist-parallel-deep-comparison">上一课</a>把四轴摆进一张对照表，DP 轴的冗余——参数、梯度、优化器状态全复制——被标成最便宜的优化起点。主干课的 <a href="/llm/zero-stages">ZeRO-1 / 2 / 3</a> 给了三档的内存公式与通信模式；本课深钻公式之外的部分：峰值水位怎么随时刻涨落、档与档之间的过渡带、以及跨轴叠加时「参数在哪」的多套下标怎么读。不重推公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公式给的是持久状态的稳态近似，训练真死在瞬时峰值：某层权重被 All-Gather 齐的那一瞬、梯度桶将满未满的一瞬，加上 NCCL 通道缓冲与分配碎片，都不在公式里。第二类缺口是叠加语义：ZeRO-3 聚集「逻辑完整层」时如果 TP 同时开着，聚集的是当前 TP 分片需要的那一块，不是整层；PP 叠上后，DP 分片组只在同阶段内成立。第三类是选档次序：什么时候停在 2、什么时候必须进 3，公式回答不了，要看通信时序。</p><p><span class="marginnote">ZeRO 一句话：DP 下每张卡都存着完整一份参数、梯度和优化器状态，其中绝大部分是重复的冗余；ZeRO 就是按档位把这份冗余切掉，每卡只留 \\(1/N\\)，要用时再靠通信临时「借」回来。</span></p><h3 id="按时刻记账" tabindex="-1">按时刻记账 <a class="header-anchor" href="#按时刻记账" aria-label="Permalink to &quot;按时刻记账&quot;">​</a></h3><p>step 内取三个采样点：前向中、反传中、优化器步。ZeRO-1 与 2 的水位平缓——参数与梯度全程在卡上，优化器分片只在步末活动；ZeRO-3 的水位是锯齿——每层权重被抬起再放下，wrap 粒度决定齿距，prefetch 把整条基线抬高一点。把峰值读成「锯齿顶点加固定项」，比读 \\(16\\Phi/N\\) 更接近真实余量。</p><p><span class="marginnote">拿 7B 模型、8 卡代一下：Adam 的两个 fp32 状态矩阵约 56 GB，不分片时每张卡都得放一份；ZeRO-1 切到每卡 7 GB——只切这一刀就省出大半张 80 GB 卡，通信几乎不变，这就是「第一刀几乎免费」。</span></p><p><span class="marginnote">梯度累积场景里，ZeRO-2 的分片缓冲必须从第一个 microbatch 就按分片累积；先在完整缓冲里攒再分片，第二档的显存收益整段消失。这是「公式对、实现亏」的高频案例。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>过渡带的代价表：1 到 2，换来 Reduce-Scatter 的时序约束——反传一结束就散，不许攒整份 \\(\\bar g\\)；2 到 3，每层 All-Gather 进关键路径，深而窄的模型先撞延迟区，再宽的层才开始被带宽区接管。3 之上的旋钮都是峰值与通信的交换：wrap 细则峰值低、次数多；前向权重留给反传用省一次通信、多占一份显存；prefetch 掩盖延迟、抬高水位。2 与 3 之间还有过渡档：节点内分片到第三档、节点间保持复制的混合分片，FSDP 的 HYBRID_SHARD 是这一档的现成接口，跨机聚集组被缩小，代价是单机容量成为下界。</p>',12)),(e(),t(s,null,{default:a(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20Z1G%5B%22ZeRO-1%22%5D%0A%20%20%20%20A1%5B%22%E5%8F%AA%E5%88%87%E4%BC%98%E5%8C%96%E5%99%A8%E7%8A%B6%E6%80%81%3A%2012%CE%A6%2FN%22%5D%20--%3E%20A2%5B%22%E9%80%9A%E4%BF%A1%E4%BD%93%E7%A7%AF%E4%B8%8D%E5%8F%98%2C%20%E5%87%A0%E4%B9%8E%E5%85%8D%E8%B4%B9%22%5D%0A%20%20end%0A%20%20subgraph%20Z2G%5B%22ZeRO-2%22%5D%0A%20%20%20%20B1%5B%22%E5%8A%A0%E5%88%87%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20B2%5B%22%E5%A4%9A%E4%B8%80%E7%AC%94%20Reduce-Scatter%2C%20%E5%8F%8D%E4%BC%A0%E4%B8%80%E7%BB%93%E6%9D%9F%E5%B0%B1%E6%95%A3%22%5D%0A%20%20end%0A%20%20subgraph%20Z3G%5B%22ZeRO-3%22%5D%0A%20%20%20%20C1%5B%22%E5%86%8D%E5%88%87%E5%8F%82%E6%95%B0%22%5D%20--%3E%20C2%5B%22%E6%AF%8F%E5%B1%82%E5%89%8D%E5%90%8E%E5%90%91%E9%83%BD%E8%A6%81%20All-Gather%2C%20%E6%AC%A1%E6%95%B0%E9%9A%8F%E5%B1%82%E6%95%B0%E6%B6%A8%22%5D%0A%20%20end%0A%20%20A2%20--%3E%20D%5B%22%E6%AF%8F%E6%B7%B1%E4%B8%80%E6%A1%A3%3A%20%E6%98%BE%E5%AD%98%E9%99%8D%E4%B8%80%E6%88%AA%2C%20%E9%80%9A%E4%BF%A1%E6%97%B6%E5%BA%8F%E7%BA%A6%E6%9D%9F%E4%B8%8A%E4%B8%80%E6%A1%A3%22%5D%0A%20%20B2%20--%3E%20D%0A%20%20C2%20--%3E%20D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"为什么三档的通信是阶跃而不是线性：第一档通信体积不变，只是更新顺手分了片；第二档起通信拆成 Reduce-Scatter 加参数 All-Gather 两笔，体积仍与 All-Reduce 同阶；第三档起每层前向、反传都要聚集，次数正比于层数乘 wrap 数——延迟项从这一档开始收税，这就是小模型上第三档反而慢的机制。跨轴下标是第三档的真实复杂度：检查点必须同时记录 DP 片与 TP 片；全局梯度范数跨分片归约，漏一次归约，等效裁剪阈值随卡数漂移；改卡数不是改配置，是按新 \\(N'\\) 重切再恢复。这些约束与档位绑定，与框架名字无关。",-1)),(e(),t(s,null,{default:a(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%89%8D%E5%90%91%E4%B8%AD%3A%20ZeRO-3%20%E6%AF%8F%E5%B1%82%20AG%20%E6%8A%AC%E8%B5%B7%E6%9D%83%E9%87%8D%22%5D%20--%3E%20S2%5B%22%E5%8F%8D%E4%BC%A0%E4%B8%AD%3A%20%E6%A2%AF%E5%BA%A6%E6%A1%B6%E5%B0%86%E6%BB%A1%20%2B%20%E9%87%8D%E6%94%BE%E5%B1%82%E6%9D%83%E9%87%8D%E5%86%8D%E6%8A%AC%E8%B5%B7%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E6%AD%A5%3A%20%E5%88%86%E7%89%87%E7%8A%B6%E6%80%81%E6%B4%BB%E5%8A%A8%2C%20%E5%8F%82%E6%95%B0%E5%B9%BF%E6%92%AD%E5%9B%9E%E5%85%A8%E5%8D%A1%22%5D%0A%20%20S3%20--%3E%20PEAK%5B%22%E5%B3%B0%E5%80%BC%20%3D%20%E9%94%AF%E9%BD%BF%E9%A1%B6%E7%82%B9%20%2B%20%E9%80%9A%E4%BF%A1%E7%BC%93%E5%86%B2%20%2B%20%E7%A2%8E%E7%89%87%22%5D%0A%20%20PEAK%20--%3E%20DECIDE%7B%22%E6%8C%81%E4%B9%85%E6%80%81%E6%94%BE%E5%BE%97%E4%B8%8B%3F%22%7D%0A%20%20DECIDE%20--%3E%7C%E6%94%BE%E5%BE%97%E4%B8%8B%7C%20STAY%5B%22%E5%81%9C%E5%9C%A8%E5%BD%93%E5%89%8D%E6%A1%A3%22%5D%0A%20%20DECIDE%20--%3E%7C%E6%94%BE%E4%B8%8D%E4%B8%8B%7C%20UP%5B%22%E5%8D%87%E6%A1%A3%E6%88%96%E6%B7%B7%E5%90%88%E5%88%86%E7%89%87%2C%20%E9%87%8D%E6%96%B0%E6%95%B0%E9%80%9A%E4%BF%A1%E6%AC%A1%E6%95%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重讲三档公式与 FSDP 档位对照（见 <a href="/llm/fsdp">FSDP</a>）；offload 是第三档向存储层级的延长，不是第四种语义，见 <a href="/llm/zero-offload">ZeRO-Offload</a> 与 <a href="/llm/zero-infinity">ZeRO-Infinity</a>。ZeRO 切的是参数侧：激活的墙不归它管，序列并行与重计算是另一条轴，下一课接手激活侧。选档口诀不变：先看哪块显存先爆，再看增加的通信次数能否被计算盖住；两个条件都过了，才值得把刀切深一档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公式给持久态，训练死在峰值；按前向、反传、优化器步三个时刻记水位。</li><li>档间是阶跃：第二档改通信结构，第三档把聚集放进关键路径，延迟项从第三档收税。</li><li>混合分片（节点内深切、节点间复制）是 2 与 3 的过渡档，跨机聚集组缩小。</li><li>跨轴叠加时多套分片下标共存：检查点、梯度范数、重切分都要按两套下标对账。</li><li>出处：Rajbhandari 等，ZeRO / DeepSpeed 系列；PyTorch FSDP 的档位对照与混合分片口径。</li></ul>',4))])}const P=i(n,[["render",p]]);export{F as __pageData,P as default};
